/** `"3:2"`, `"9:16"`, or a number (width over height). */
export type AspectRatio = `${number}:${number}` | number

/* -------------------------------------------------------------------------------------------------
 * Helpers
 * -----------------------------------------------------------------------------------------------*/

/** `"3:2"` to 1.5. Falls back to 1 for anything it cannot read. */
export function parseAspectRatio(ratio: AspectRatio | undefined): number {
  if (typeof ratio === "number") return ratio > 0 ? ratio : 1
  if (!ratio) return 1
  const [w, h] = ratio.split(":").map(Number)
  return w && h && w > 0 && h > 0 ? w / h : 1
}

/* -------------------------------------------------------------------------------------------------
 * Types
 * -----------------------------------------------------------------------------------------------*/

/** Where a generation job is. `blocked` means the provider declined the prompt. */
export type GenerationStatus = "queued" | "generating" | "done" | "failed" | "blocked"

export interface GeneratedImage {
  /** Stable id. Falls back to `src`. */
  id?: string
  /**
   * The image. While generating, pass the latest partial image here: it is revealed from the top
   * as `progress` grows. Leave it out when the provider sends nothing until the end.
   */
  src?: string
  /** A tiny low-resolution version shown blurred behind the reveal. Defaults to `src`. */
  previewSrc?: string
  /** Describe what the image shows. Defaults to the prompt. */
  alt?: string
  width?: number
  height?: number
  /** File name for downloads. Derived from the prompt when omitted. */
  filename?: string
  /** Per-image progress, 0 to 100, when variations finish at different speeds. */
  progress?: number
}

export type ImageGenerationAction = "upscale" | "vary" | "reference"

export interface ImageGenerationProps extends Omit<React.ComponentProps<"div">, "onSelect"> {
  prompt: string
  status: GenerationStatus
  images?: GeneratedImage[]
  /** Number of variations, 1 to 4. Defaults to the number of images. */
  count?: number
  /** Default `"1:1"`. Sets every frame's shape from the first paint, so nothing shifts. */
  aspectRatio?: AspectRatio
  /** 0 to 100 while generating. Leave it out when the provider reports no progress. */
  progress?: number
  /**
   * Time left in ms, from the provider. When it is left out and `progress` moves, the time left is
   * measured from the progress rate, and only shown once there is enough to go on.
   */
  etaMs?: number
  /** Place in line while queued. 1 means next. */
  queuePosition?: number
  /** Override the status label. Defaults to "Creating image", then "Adding details". */
  statusText?: string
  /** Short facts after the aspect ratio in the summary line: a model, a style, a seed. */
  settings?: React.ReactNode[]
  /** Show the prompt and settings above the images. Turn off inside a tool call. */
  showPrompt?: boolean
  errorText?: React.ReactNode
  /** Why the provider declined. Keep it calm and say what to change. */
  blockedText?: React.ReactNode
  onRetry?: () => void
  onCancel?: () => void
  /** Shown on a blocked prompt so the user can rephrase it. */
  onEditPrompt?: () => void
  onUpscale?: (image: GeneratedImage, index: number) => void
  onVary?: (image: GeneratedImage, index: number) => void
  onUseAsReference?: (image: GeneratedImage, index: number) => void
  /** Replace the built-in download link, for example for cross-origin files. */
  onDownload?: (image: GeneratedImage, index: number) => void
  /** An action in flight. Its button shows a spinner and the others wait. */
  busyAction?: ImageGenerationAction
  /** The variation the actions apply to. */
  selectedIndex?: number
  defaultSelectedIndex?: number
  onSelectedIndexChange?: (index: number) => void
}

const clampCount = (n: number) => Math.min(4, Math.max(1, Math.round(n)))

/** Columns by count. Four portrait frames sit in one row; four others make a square. */
function columnsFor(total: number, ratio: number) {
  if (total === 4) return ratio < 1 ? 4 : 2
  return total
}

/* -------------------------------------------------------------------------------------------------
 * Types
 * -----------------------------------------------------------------------------------------------*/

interface ImageSource {
  src: string
  /** Required. Describe what the image shows, not that it is an image. */
  alt: string
  /** Intrinsic size. Sets the placeholder's aspect ratio so nothing shifts when it loads. */
  width?: number
  height?: number
  /** A tiny low-resolution version (a data URL works) shown blurred until the image loads. */
  placeholder?: string
  /** Optional caption under the image and in the lightbox. */
  caption?: React.ReactNode
  /** File name for downloads. Defaults to the last part of `src`. */
  filename?: string
}

function slugify(text: string) {
  return (
    text
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, " ")
      .trim()
      .split(" ")
      .slice(0, 5)
      .join("-") || "image"
  )
}

function extensionOf(src: string) {
  const data = /^data:image\/([a-z]+)/i.exec(src)
  if (data?.[1]) return data[1] === "jpeg" ? "jpg" : data[1]
  const path = /\.([a-z0-9]{2,4})(?:[?#]|$)/i.exec(src)
  return path?.[1] ?? "png"
}

function downloadName(image: GeneratedImage, prompt: string, index: number, total: number) {
  if (image.filename) return image.filename
  const suffix = total > 1 ? `-${index + 1}` : ""
  return `${slugify(prompt)}${suffix}.${extensionOf(image.src ?? "")}`
}

/** Status label from progress. Specific words beat a bare percentage. */
export function generationStage(progress: number | undefined, plural: boolean) {
  if (progress === undefined || progress < 30) return plural ? "Creating images" : "Creating image"
  if (progress < 80) return "Adding details"
  return "Finishing"
}

interface UseChatcnMediaEtaOptions {
  /** True while the job is generating. The estimate resets when a new run starts. */
  active: boolean
  /** An estimate from the server. Wins over the measured one when present. */
  etaMs?: number
}

/**
 * Time left for a generation job, in ms, from how fast `progress` (0 to 100) has moved so far.
 *
 * It waits for 2 s and 3 points of progress before guessing, smooths the rate so one slow step
 * does not double the estimate, and counts down once per second between progress updates. The
 * estimate never goes up by less than 5 s, so the label does not flicker between two values.
 */
function useChatcnMediaEta(
  progress: number | undefined,
  { active, etaMs }: UseChatcnMediaEtaOptions,
): number | undefined {
  const start = React.useRef<{ t: number; p: number } | null>(null)
  const rate = React.useRef<number | null>(null)
  const [estimate, setEstimate] = React.useState<{ ms: number; at: number } | null>(null)
  // Starts empty and reads the clock after mount: a render must not read it (Next.js prerender).
  const [now, setNow] = React.useState<number | null>(null)

  React.useEffect(() => {
    if (!active) {
      start.current = null
      rate.current = null
      setEstimate(null)
      return
    }
    if (progress === undefined) return
    const t = Date.now()
    if (!start.current) {
      start.current = { t, p: progress }
      return
    }
    const dt = t - start.current.t
    const dp = progress - start.current.p
    if (dt < 2000 || dp < 3) return
    const measured = dp / dt
    // Exponential smoothing: new samples count for 30%.
    rate.current = rate.current === null ? measured : rate.current * 0.7 + measured * 0.3
    const ms = Math.max(0, (100 - progress) / rate.current)
    setEstimate((prev) => {
      if (prev) {
        const shown = prev.ms - (t - prev.at)
        if (ms > shown && ms - shown < 5000) return prev
      }
      return { ms, at: t }
    })
  }, [active, progress])

  React.useEffect(() => {
    if (!active) return
    const id = window.setInterval(() => setNow(Date.now()), 1000)
    return () => window.clearInterval(id)
  }, [active])

  if (!active) return undefined
  if (etaMs !== undefined) return etaMs
  if (!estimate) return undefined
  return Math.max(0, estimate.ms - ((now ?? estimate.at) - estimate.at))
}

const NBSP = " "

/**
 * Formats a duration the chatcn way: numerals, a non-breaking space before the unit.
 * `precise` (the default) keeps a decimal under 10 s and milliseconds under 1 s, for finished
 * steps. Turn it off for live counters and "Thought for 12 s", which read in whole seconds.
 */
function formatChatcnDuration(ms: number, { precise = true }: { precise?: boolean } = {}) {
  const safe = Math.max(0, ms)
  if (precise && safe < 1000) return `${Math.max(1, Math.round(safe))}${NBSP}ms`
  const s = safe / 1000
  if (precise && s < 10) return `${s.toFixed(1)}${NBSP}s`
  if (s < 60) return `${precise ? Math.round(s) : Math.floor(s)}${NBSP}s`
  const totalS = Math.floor(s)
  const h = Math.floor(totalS / 3600)
  const m = Math.floor((totalS % 3600) / 60)
  const rest = totalS % 60
  if (h > 0) return `${h}${NBSP}h ${m}${NBSP}m`
  return `${m}${NBSP}m ${rest}${NBSP}s`
}

/**
 * The time left, said the way a person would: rounded up to 5 s under a minute and 10 s above,
 * so it counts down in calm steps instead of ticking every second.
 */
export function generationEtaLabel(ms: number | undefined, progress: number | undefined) {
  if (ms === undefined) return null
  if (ms < 5000) return (progress ?? 0) >= 90 ? "Almost done" : "A few seconds left"
  const step = ms < 60_000 ? 5000 : 10_000
  return `About ${formatChatcnDuration(Math.ceil(ms / step) * step, { precise: false })} left`
}

type ButtonVariant = "solid" | "outline" | "ghost" | "subtle"

type ButtonSize = "xs" | "sm" | "md" | "lg" | "icon-xs" | "icon-sm" | "icon-md" | "icon-lg"

interface ButtonProps extends React.ComponentProps<"button"> {
  variant?: ButtonVariant
  size?: ButtonSize
}

interface CopyButtonProps extends Omit<ButtonProps, "value" | "onCopy"> {
  value: string | (() => string)
  label?: string
  onCopy?: (value: string) => void
}

const base = cn(
  "chatcn-focus inline-flex shrink-0 items-center justify-center gap-1.5 font-medium whitespace-nowrap select-none",
  "ease-(--chatcn-ease-standard) transition-[background-color,color,box-shadow,scale] duration-150",
  "active:scale-(--chatcn-press-scale) active:duration-100 disabled:pointer-events-none disabled:opacity-50",
  "[&_svg]:pointer-events-none [&_svg]:shrink-0",
)

const variants: Record<ButtonVariant, string> = {
  solid: "bg-(color:--chatcn-primary) text-(color:--chatcn-primary-fg) hover:bg-(color:--chatcn-primary-hover)",
  outline: "bg-(color:--chatcn-card) text-(color:--chatcn-fg) shadow-(--chatcn-shadow-xs) hover:bg-(color:--chatcn-fill-hover)",
  ghost: "text-(color:--chatcn-fg-muted) hover:bg-(color:--chatcn-fill-hover) hover:text-(color:--chatcn-fg)",
  subtle: "bg-(color:--chatcn-fill) text-(color:--chatcn-fg) hover:bg-(color:--chatcn-fill-hover)",
}

// Heights follow the control scale: 24, 28, 32, 36. Radii stay concentric inside 12 px surfaces.
const sizes: Record<ButtonSize, string> = {
  xs: "h-6 rounded-(--chatcn-radius-sm) px-2 text-[0.75rem]/[1rem] [&_svg]:size-3.5",
  sm: "h-7 rounded-(--chatcn-radius-sm) px-2.5 text-[0.8125rem]/[1.25rem] [&_svg]:size-3.5",
  md: "h-8 rounded-(--chatcn-radius-md) px-3 text-[0.875rem]/[1.25rem] tracking-[-0.003em] [&_svg]:size-4",
  lg: "h-9 rounded-(--chatcn-radius-md) px-3.5 text-[0.875rem]/[1.25rem] tracking-[-0.003em] [&_svg]:size-4",
  "icon-xs": "size-6 rounded-(--chatcn-radius-sm) active:scale-(--chatcn-press-scale-icon) [&_svg]:size-3.5",
  "icon-sm": "size-7 rounded-(--chatcn-radius-sm) active:scale-(--chatcn-press-scale-icon) [&_svg]:size-3.5",
  "icon-md": "size-8 rounded-(--chatcn-radius-md) active:scale-(--chatcn-press-scale-icon) [&_svg]:size-4",
  "icon-lg": "size-9 rounded-(--chatcn-radius-md) active:scale-(--chatcn-press-scale-icon) [&_svg]:size-4",
}

/** Class names for anything that should look like a button, such as a link. */
function buttonVariants({
  variant = "ghost",
  size = "md",
}: {
  variant?: ButtonVariant
  size?: ButtonSize
} = {}) {
  return cn(base, variants[variant], sizes[size])
}

function Button({
  variant = "ghost",
  size = "md",
  type = "button",
  className,
  ...props
}: ButtonProps) {
  return (
    <button
      type={type}
      data-slot="button"
      data-variant={variant}
      className={cn(buttonVariants({ variant, size }), className)}
      {...props}
    />
  )
}

interface IconProps extends SVGAttributes<SVGSVGElement> {
  /** Width and height. Number means px. Default 24. */
  size?: number | string
  /** Stroke width in viewBox units (24 grid). Default 1.5. */
  strokeWidth?: number | string
  /** Keep the rendered stroke at `strokeWidth` px at any size. */
  absoluteStrokeWidth?: boolean
  /** Stroke color. Default currentColor. */
  color?: string
  /** Accessible name. Renders <title> and sets role="img"; without it the icon is aria-hidden. */
  title?: string
}

type Icon = ForwardRefExoticComponent<IconProps & RefAttributes<SVGSVGElement>>

/** Shape elements an icon may contain. */
type IconElement = "path" | "circle" | "rect" | "ellipse" | "line" | "polyline" | "polygon"

/** An icon's drawing: a flat list of [element, attributes] pairs, lucide compatible. */
type IconNode = ReadonlyArray<readonly [IconElement, Readonly<Record<string, string>>]>

const toPascal = (name: string): string =>
  name
    .split("-")
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join("")

/**
 * Builds a React icon component from an icon node.
 * `name` is the kebab-case icon name, used for the class `chatcn-icon-<name>` and displayName.
 */
function createIcon(name: string, iconNode: IconNode): Icon {
  // biome-ignore lint/correctness/noComponentHookFactories: runs once per icon at module load
  const Component = forwardRef<SVGSVGElement, IconProps>(function ChatcnIcon(
    {
      size = 24,
      strokeWidth = 1.5,
      absoluteStrokeWidth = false,
      color = "currentColor",
      title,
      className,
      children,
      ...rest
    },
    ref,
  ) {
    const stroke = absoluteStrokeWidth
      ? (Number(strokeWidth) * 24) / Number.parseFloat(String(size))
      : strokeWidth
    const labelled = Boolean(title || rest["aria-label"] || rest["aria-labelledby"])
    return createElement(
      "svg",
      {
        ref,
        xmlns: "http://www.w3.org/2000/svg",
        width: size,
        height: size,
        viewBox: "0 0 24 24",
        fill: "none",
        stroke: color,
        strokeWidth: stroke,
        strokeLinecap: "round",
        strokeLinejoin: "round",
        "data-slot": "icon",
        className: className
          ? `chatcn-icon chatcn-icon-${name} ${className}`
          : `chatcn-icon chatcn-icon-${name}`,
        ...(labelled ? { role: "img" } : { "aria-hidden": true }),
        ...rest,
      },
      title ? createElement("title", null, title) : null,
      ...iconNode.map(([tag, attrs], i) => createElement(tag, { key: i, ...attrs })),
      children,
    )
  })
  Component.displayName = `${toPascal(name)}Icon`
  return Component
}

const iconNode: IconNode = [
  ["path", {"d":"M11.5 9h7a2.5 2.5 0 0 1 2.5 2.5v7a2.5 2.5 0 0 1-2.5 2.5h-7A2.5 2.5 0 0 1 9 18.5v-7A2.5 2.5 0 0 1 11.5 9"}],
  ["path", {"d":"M6 15h-.5A2.5 2.5 0 0 1 3 12.5v-7A2.5 2.5 0 0 1 5.5 3h7A2.5 2.5 0 0 1 15 5.5V6"}],
]

const CopyIcon: Icon = /* @__PURE__ */ createIcon("copy", iconNode)

const iconNode2: IconNode = [
  ["path", {"d":"m4.5 12.75 3.23 3.23a2.5 2.5 0 0 0 3.54 0l8.48-8.48"}],
]

const CheckIcon: Icon = /* @__PURE__ */ createIcon("check", iconNode2)

/** Copy swaps to a check with a 150 ms blur crossfade, holds for 1.5 s and announces itself. */
function CopyButton({
  value,
  label = "Copy",
  onCopy,
  onClick,
  children,
  size = "icon-sm",
  className,
  ...props
}: CopyButtonProps) {
  // A counter, not a flag: copying again while the check shows restarts the 1.5 s hold.
  const [copies, setCopies] = React.useState(0)
  const [copied, setCopied] = React.useState(false)
  React.useEffect(() => {
    if (!copies) return
    setCopied(true)
    const id = window.setTimeout(() => setCopied(false), 1500)
    return () => window.clearTimeout(id)
  }, [copies])

  // Reduced motion keeps the crossfade and drops the scale and blur.
  const layer = cn(
    "ease-(--chatcn-ease-out) absolute transition-[opacity,scale,filter] duration-150",
    "motion-reduce:scale-100 motion-reduce:blur-none motion-reduce:transition-opacity",
  )
  return (
    <Button
      {...props}
      size={size}
      aria-label={children ? undefined : copied ? "Copied" : label}
      onClick={(event) => {
        // Compose with handlers injected by wrappers such as Tooltip instead of replacing them.
        onClick?.(event)
        if (event.defaultPrevented) return
        const text = typeof value === "function" ? value() : value
        navigator.clipboard
          ?.writeText(text)
          .then(() => {
            setCopies((n) => n + 1)
            onCopy?.(text)
          })
          // Clipboard access can be denied (insecure context, permissions). Stay quiet and unchanged.
          .catch(() => {})
      }}
      className={cn("relative", className)}
    >
      {children ? (
        <>
          <span className="relative grid size-3.5 place-items-center">
            <CopyIcon
              className={cn(
                layer,
                copied ? "scale-75 opacity-0 blur-[2px]" : "scale-100 opacity-100",
              )}
            />
            <CheckIcon
              className={cn(
                layer,
