function filenameFrom(src: string, fallback = "image") {
  try {
    const path = new URL(src, "https://x.invalid").pathname
    const last = decodeURIComponent(path.split("/").pop() ?? "")
    return last || fallback
  } catch {
    return fallback
  }
}

