"use client"

import * as React from "react"
import { AspectRatio, GeneratedImage, ImageGeneration, ImageGenerationAction } from "@/components/ui/image-generation"

/** The slowest variation's run, then a beat on the finished set while the pick moves. */
const GENERATE_MS = 3600

/**
 * The preview opens early in the first run, so the first frame is already mid reveal and the
 * recording catches it finishing, the pick moving and the next prompt coming in.
 */
const START_MS = GENERATE_MS * 0.18

/** How long a choice holds a tour before it carries on. */
const RESUME_MS = 1800

/** True until `RESUME_MS` after the last `hold()`, for tours with their own state. */
function useHold() {
  const [held, setHeld] = React.useState(false)
  const timer = React.useRef(0)
  React.useEffect(() => () => window.clearTimeout(timer.current), [])
  const hold = React.useCallback(() => {
    setHeld(true)
    window.clearTimeout(timer.current)
    timer.current = window.setTimeout(() => setHeld(false), RESUME_MS)
  }, [])
  return [held, hold] as const
}

const reducedMotion = () => window.matchMedia("(prefers-reduced-motion: reduce)").matches

const DONE_MS = 2300

const ROUND_MS = GENERATE_MS + DONE_MS

interface Job {
  prompt: string
  aspectRatio: AspectRatio
  settings: string[]
  images: { src: string; alt: string }[]
}

// picsum.photos id 823, 640 x 800, 360 wide thumbnail, inline so the 21st preview needs no image host.
const beanie = {
  alt: "A woman in a red beanie raising a film camera to her eye in a forest",
  width: 360,
  height: 450,
  src: "data:image/webp;base64,",
}

// picsum.photos id 91, 640 x 800, 360 wide thumbnail, inline so the 21st preview needs no image host.
const camera = {
  alt: "A man in a dark sweater holding a twin lens reflex camera at chest height",
  width: 360,
  height: 450,
  src: "data:image/webp;base64,",
}

// picsum.photos id 836, 640 x 800, 360 wide thumbnail, inline so the 21st preview needs no image host.
const guitar = {
  alt: "A woman in a hat playing a red electric guitar in a record shop",
  width: 360,
  height: 450,
  src: "data:image/webp;base64,",
}

// picsum.photos id 64, 640 x 640, 360 wide thumbnail, inline so the 21st preview needs no image host.
const daisies = {
  alt: "A woman in sunglasses holding a bunch of daisies in a summer field",
  width: 360,
  height: 360,
  src: "data:image/webp;base64,",
}

// picsum.photos id 433, 640 x 800, 360 wide thumbnail, inline so the 21st preview needs no image host.
const bear = {
  alt: "Close portrait of a brown bear looking straight at the camera",
  width: 360,
  height: 450,
  src: "data:image/webp;base64,",
}

// picsum.photos id 1074, 800 x 600, 360 wide thumbnail, inline so the 21st preview needs no image host.
const lioness = {
  alt: "A lioness lying in the grass, eyes on the camera",
  width: 360,
  height: 270,
  src: "data:image/webp;base64,",
}

// picsum.photos id 659, 720 x 540, 360 wide thumbnail, inline so the 21st preview needs no image host.
const husky = {
  alt: "A husky in a harness at dusk, head turned toward the light",
  width: 360,
  height: 270,
  src: "data:image/webp;base64,",
}

/** Two prompts that take turns, each with its own shape and number of variations. */
const JOBS: Job[] = [
  {
    prompt:
      "Film portraits of photographers and musicians outdoors, warm natural light, shallow depth of field",
    aspectRatio: "4:5",
    settings: ["Umber 2", "Seed 48213"],
    images: [beanie, camera, guitar, daisies],
  },
  {
    prompt: "Animal portraits in low evening light, eyes toward the lens, soft dark background",
    aspectRatio: "4:3",
    settings: ["Umber 2", "Seed 7730"],
    images: [bear, lioness, husky],
  },
]

const PICK_MS = 520

/** Variations finish at slightly different speeds, like they do on real providers. */
const SPEED = [1, 0.84, 0.93, 0.78]

const FIT_CSS = "html,body{overflow:hidden}[data-fit-small] [data-fit-hide]{display:none!important}"

/**
 * 21st shows a demo in a small frame: about 674 by 421 on a component page, 358 by 224 on a
 * phone and 245 by 139 on a profile card. A demo taller than its frame gets scrollbars, which
 * render white on dark pages. FitFrame fills the frame exactly instead.
 *
 * - "scale": the content shrinks until it fits, centered. For visuals such as orbs.
 * - "crop": the content stays at full size from the top and fades out at the bottom. For text
 *   that streams in, where a changing scale would make the page breathe.
 *
 * `minWidth` lays out a wide demo (a table, a two column panel) at that width and scales it down
 * to the frame, instead of letting it collapse to a narrow layout. The frame centers it, so it
 * shrinks evenly on both sides.
 *
 * Anything marked `data-fit-hide` (state buttons, the chatcn.dev line) drops out in frames
 * shorter than `hideBelow`, so a profile card shows the visual alone.
 */
function FitFrame({
  children,
  mode = "scale",
  hideBelow = 360,
  minWidth,
}: {
  children: React.ReactNode
  mode?: "scale" | "crop"
  hideBelow?: number
  minWidth?: string
}) {
  const content = React.useRef<HTMLDivElement>(null)
  const [cropped, setCropped] = React.useState(false)

  React.useLayoutEffect(() => {
    const el = content.current
    if (!el) return
    const measure = () => {
      const vw = window.innerWidth
      const vh = window.innerHeight
      el.toggleAttribute("data-fit-small", vh < hideBelow)
      // Layout sizes ignore the transform, so measuring never feeds back.
      const w = Math.max(el.offsetWidth, el.scrollWidth)
      const h = Math.max(el.offsetHeight, el.scrollHeight)
      const scale = mode === "scale" ? Math.min(1, vw / w, vh / h) : 1
      el.style.transform = scale < 1 ? `scale(${scale})` : ""
      setCropped(mode === "crop" && h > vh + 1)
    }
    measure()
    const observer = new ResizeObserver(measure)
    observer.observe(el)
    // Content that changes inside a fixed width box (a headline that cycles words) never resizes
    // the box itself, so changes below it measure again on the next frame.
    let frame = 0
    const mutations = new MutationObserver(() => {
      cancelAnimationFrame(frame)
      frame = requestAnimationFrame(measure)
    })
    mutations.observe(el, { subtree: true, childList: true, characterData: true })
    window.addEventListener("resize", measure)
    return () => {
      observer.disconnect()
      mutations.disconnect()
      cancelAnimationFrame(frame)
      window.removeEventListener("resize", measure)
    }
  }, [mode, hideBelow])

  const fade = "linear-gradient(to bottom, #000 calc(100% - 40px), transparent)"
  return (
    <div
      className="flex w-full justify-center overflow-hidden"
      style={{
        height: "100dvh",
        alignItems: mode === "crop" ? "flex-start" : "center",
        maskImage: cropped ? fade : undefined,
        WebkitMaskImage: cropped ? fade : undefined,
      }}
    >
      <style>{FIT_CSS}</style>
      <div
        ref={content}
        className="w-full shrink-0"
        style={{ transformOrigin: mode === "crop" ? "top center" : "center", minWidth }}
      >
        {children}
      </div>
    </div>
  )
}

/** The line under each 21st demo that points back to the kit. */
function MoreOn({ slug, children }: { slug: string; children: React.ReactNode }) {
  return (
    <p data-fit-hide className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-faint) text-center text-balance">
      {children}{" "}
      <a
        href={`https://chatcn.dev/docs/components/${slug}`}
        target="_blank"
        rel="noopener"
        className="text-(color:--chatcn-fg-subtle) hover:text-(color:--chatcn-fg) underline underline-offset-2"
      >
        chatcn.dev
      </a>
    </p>
  )
}

/**
 * Prompts render one after another: variations sharpen in from the top behind a scan line, each
 * at its own speed, the time left settles, then the actions arrive and the pick moves across the
 * set. Click a variation or an action and the tour waits a moment, then carries on.
 */
export default function ImageGenerationPreview() {
  const [clock, setClock] = React.useState(START_MS)
  const [held, hold] = useHold()
  const [mine, setMine] = React.useState(0)
  const [busy, setBusy] = React.useState<ImageGenerationAction>()

  React.useEffect(() => {
    if (held) return
    if (reducedMotion()) {
      setClock(GENERATE_MS + 400)
      return
    }
    const began = performance.now() - clock
    const id = window.setInterval(() => setClock(performance.now() - began), 60)
    return () => window.clearInterval(id)
    // biome-ignore lint/correctness/useExhaustiveDependencies: resumes from the clock it held at.
  }, [held])

  const round = Math.floor(clock / ROUND_MS)
  const local = clock % ROUND_MS
  const job = JOBS[round % JOBS.length]!
  const generating = local < GENERATE_MS
  const progress = Math.min(100, (local / GENERATE_MS) * 100)
  const tourPick = Math.min(
    job.images.length - 1,
    Math.max(0, Math.floor((local - GENERATE_MS - 400) / PICK_MS)),
  )

  const images: GeneratedImage[] = job.images.map((photo, i) => ({
    id: `${round}-${i}`,
    src: photo.src,
    alt: photo.alt,
    progress: generating ? Math.min(100, progress / (SPEED[i] ?? 1)) : undefined,
  }))

  const selected = held ? mine : tourPick
  const act = (action: ImageGenerationAction) => {
    hold()
    setMine(selected)
    setBusy(action)
    window.setTimeout(() => setBusy(undefined), 900)
  }

  return (
    <FitFrame minWidth="40rem">
      <div className="flex w-full flex-col items-center justify-center gap-6 p-8">
        <div className="flex min-h-[19.5rem] w-full max-w-2xl flex-col justify-center">
          <ImageGeneration
            // A new prompt is a new job: the frames start from grain again.
            key={round}
            prompt={job.prompt}
            status={generating ? "generating" : "done"}
            progress={generating ? progress : undefined}
            aspectRatio={job.aspectRatio}
            count={job.images.length}
            images={images}
            settings={job.settings}
            selectedIndex={selected}
            onSelectedIndexChange={(i) => {
              hold()
              setMine(i)
            }}
            busyAction={busy}
            onCancel={() => {
              hold()
              setMine(selected)
            }}
            onUpscale={() => act("upscale")}
            onVary={() => act("vary")}
            onUseAsReference={() => act("reference")}
          />
        </div>
        <MoreOn slug="image-generation">
          Progressive reveal, variations and actions for any image model. On
        </MoreOn>
      </div>
    </FitFrame>
  )
}
